const events=[{id:"mie-iseebi",pref:P,name:T("이세에비마쓰리","伊勢えび祭"),area:A.shima,months:[6],timing:T("2026년 6월 6일","2026年6月6日"),scheduleType:T("2026년 개최 완료","2026年開催済み"),type:T("이세에비·춤·신여","伊勢海老・踊り・神輿"),description:T("해산물의 풍어와 안전을 기원하며 자콧페춤과 이세에비 신여가 이어지는 하마지마의 대표 축제입니다.","豊漁と海上安全を祈り、じゃこっぺ踊りと伊勢えびみこしが続く浜島を代表する祭りです。"),source:"https://www.kankomie.or.jp/topic/1230"},{id:"mie-ishidori",pref:P,name:T("구와나 이시도리마쓰리","桑名石取祭"),area:A.hokusei,months:[8],timing:T("2026년 8월 1~2일","2026年8月1〜2日"),scheduleType:T("2026년 개최 완료","2026年開催済み"),type:T("제차·징·북·유네스코","祭車・鉦・太鼓・ユネスコ"),description:T("수십 대의 화려한 제차가 징과 북을 울리며 구와나 시가지를 도는 유네스코 무형문화유산 구성 축제입니다.","数十台の豪華な祭車が鉦と太鼓を打ち鳴らして桑名市街を巡る、ユネスコ無形文化遺産の構成行事です。"),source:"https://www.kankomie.or.jp/event/35039"},{id:"mie-kumano",pref:P,name:T("구마노 대불꽃대회","熊野大花火大会"),area:A.kishu,months:[8],timing:T("2026년 8월 17일","2026年8月17日"),scheduleType:T("2026년 개최 완료","2026年開催済み"),type:T("불꽃·오니가조·해상","花火・鬼ヶ城・海上"),description:T("오니가조 암벽과 구마노나다를 무대로 해상자폭·대형 장치불꽃이 펼쳐지는 히가시키슈 최대급 여름행사입니다.","鬼ヶ城の岩壁と熊野灘を舞台に海上自爆や大仕掛け花火が展開する東紀州最大級の夏行事です。"),source:"https://www.kankomie.or.jp/event/5207.html"},{id:"mie-tsu",pref:P,name:T("쓰마쓰리","津まつり"),area:A.chunan,months:[10],timing:T("2026년 10월 9~11일","2026年10月9〜11日"),scheduleType:T("2026년 공식 일정","2026年公式日程"),type:T("향토예능·요사코이·퍼레이드","郷土芸能・よさこい・パレード"),description:T("도진오도리·샤고우마 등 향토예능과 안노쓰 요사코이가 도심에서 이어지는 미에현 대형 가을축제입니다.","唐人踊り、しゃご馬などの郷土芸能と安濃津よさこいが市街地で続く三重県最大級の秋祭りです。"),source:"https://www.kankomie.or.jp/event/5236.html"},{id:"mie-ueno",pref:P,name:T("우에노텐진마쓰리","上野天神祭"),area:A.iga,months:[10],timing:T("2026년 10월 23~25일","2026年10月23〜25日"),scheduleType:T("2026년 공식 일정","2026年公式日程"),type:T("오니행렬·단지리·유네스코","鬼行列・だんじり・ユネスコ"),description:T("오니행렬과 아홉 대의 화려한 단지리가 이가우에노 성하마을을 도는 400년 전통의 가을축제입니다.","鬼行列と九基の豪華なだんじりが伊賀上野城下町を巡る400年以上の伝統を持つ秋祭りです。"),source:"https://www.kankomie.or.jp/event/5285"},{id:"mie-akame",pref:P,name:T("아카메 48폭포 단풍","赤目四十八滝の紅葉"),area:A.iga,months:[11],timing:T("예년 11월 상순~하순","例年11月上旬〜下旬"),scheduleType:T("계절 참고","季節目安"),type:T("단풍·폭포·계곡","紅葉・滝・渓谷"),description:T("약 4km 계곡의 단풍과 여러 폭포가 겹쳐지는 나바리의 대표 가을 풍경입니다.","約4kmの渓谷で紅葉と多くの滝が重なる名張を代表する秋景色です。"),source:"https://www.kankomie.or.jp/event/34566"},{id:"mie-nabana",pref:P,name:T("나바나노사토 일루미네이션","なばなの里イルミネーション"),area:A.hokusei,months:[10,11,12,1,2,3,4,5],timing:T("2026년 10월 17일~2027년 5월 31일","2026年10月17日〜2027年5月31日"),scheduleType:T("2026~27 공식 일정","2026〜27公式日程"),type:T("일루미네이션·정원·야경","イルミネーション・庭園・夜景"),description:T("대형 테마 연출과 빛의 터널, 계절꽃 조명을 함께 즐기는 나바나노사토의 장기 야간행사입니다.","大型テーマ演出、光のトンネル、季節の花のライトアップを楽しめるなばなの里の長期夜間イベントです。"),source:"https://www.nagashima-onsen.co.jp/nabana/illumination/index.html"}];
const intros={[P]:["",T("이세신궁과 이세시마의 리아스식 해안, 닌자문화·도카이도 역참, 브랜드 음식, 구마노고도 세계유산까지 역사·바다·산악이 크게 갈리는 종합 여행지입니다.","伊勢神宮と伊勢志摩のリアス海岸、忍者文化・東海道宿場、ブランドグルメ、熊野古道世界遺産まで、歴史・海・山が大きく分かれる総合旅行地です。")],[A.ise]:["ISE · FUTAMI",T("이세신궁 내·외궁을 중심으로 오카게요코초와 부부바위까지 전통 참배문화와 몬젠마치 먹거리를 즐기는 핵심권역입니다.","伊勢神宮の内宮・外宮を中心に、おかげ横丁と夫婦岩まで参宮文化と門前町グルメを楽しむ中心エリアです。")],[A.shima]:["TOBA · SHIMA",T("도바의 수족관·진주문화와 시마의 아고만 전망·리조트·해산물이 이어지는 이세시마 해양관광의 중심입니다.","鳥羽の水族館・真珠文化と志摩の英虞湾展望・リゾート・海産物が続く伊勢志摩海洋観光の中心です。")],[A.hokusei]:["HOKUSEI · SUZUKA",T("나가시마의 테마파크·쇼핑·일루미네이션부터 고자이쇼 산악과 스즈카서킷, 세키주쿠까지 가족여행과 드라이브에 강한 북부권입니다.","長島のテーマパーク・買い物・イルミネーションから御在所の山岳、鈴鹿サーキット、関宿まで、家族旅行とドライブに強い北部エリアです。")],[A.iga]:["IGA · NABARI",T("닌자문화가 남은 이가우에노와 폭포·계곡이 깊은 나바리를 함께 묶어 역사체험과 자연산책을 즐기는 서부권입니다.","忍者文化が残る伊賀上野と、滝・渓谷の深い名張を組み合わせ、歴史体験と自然散策を楽しむ西部エリアです。")],[A.chunan]:["MATSUSAKA · TSU",T("마쓰사카성·무가저택과 마쓰사카규, 쓰의 오래된 사찰·온천, VISON의 현대적인 식문화가 섞이는 중부권입니다.","松坂城・武家屋敷と松阪牛、津の古寺・温泉、VISONの現代的な食文化が混ざる中部エリアです。")],[A.kishu]:["EAST KISHU",T("구마노고도 이세지의 돌길과 오니가조·나나리미하마·센마이다가 이어져 긴 이동 대신 숙박을 두고 천천히 보는 자연·순례권입니다.","熊野古道伊勢路の石畳と鬼ヶ城・七里御浜・千枚田が続き、長距離移動より宿泊を入れてゆっくり巡る自然・巡礼エリアです。")]};const heroes={[A.ise]:3700,[A.shima]:3706,[A.hokusei]:3712,[A.iga]:3719,[A.chunan]:3721,[A.kishu]:3726};
